INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (907, 10, 1, 'وجَّهتُ وجهيَ للذي فَطَرَ السماواتِ والأرضَ حنيفًا مسلمًا، وما أنا من المشركين، إنَّ صلاتي ونُسُكي ومحيايَ ومماتي للهِ ربِّ العالمين، لا شريكَ له، وبذلك أُمِرْتُ، وأنا أوَّلُ المسلمين. اللهم أنتَ المَلِكُ، لا إله إلا أنت، سبحانَك وبحمدِكَ، أنتَ رَبِّي، وأنا عبدُكَ، ظَلَمْتُ نفسي، واعترفتُ بذنبي، فاغفرْ لي ذنوبي جميعًا، إنه لا يغفرُ الذنوبَ إلا أنت، واهدِني لأحسنِ الأخلاق، لا يَهْدِي لأحسنِها إلا أنت، واصرِفْ عني سيِّئَها، لا يَصْرِفُ عني سيِّئَها إلا أنت، لَبَّيْكَ وَسَعْدَيْكَ، والخيرُ كلُّه في يديك، والشَّرُّ ليس إليك، لا مَنجا ولا مَلجأ منك إلا إليك، تباركتَ وتعاليتَ، أستغفرُكَ وأتوبُ إليك', 1, 'ما يقول بعد تكبيرة الإحرام ويُسمَّى دعاء الاستفتاح (أو التوجُّه). (ص91–93)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (908, 10, 2, 'اللهمَّ بَاعِدْ بيني وبين خطايايَ كما باعدتَ بين المشرقِ والمغربِ، اللهمَّ نَقِّني من خطايايَ كما يُنقَّى الثوبُ الأبيضُ من الدَّنَسِ، اللهمَّ اغسِلْني من خطايايَ بالماءِ والثلجِ والبَرَدِ', 1, 'ما يقول بعد تكبيرة الإحرام ويُسمَّى دعاء الاستفتاح (أو التوجُّه). (ص93)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (909, 10, 3, 'سبحانَك اللهمَّ وبحمدِكَ، وتبارك اسمُكَ، وتعالى جَدُّكَ، ولا إله غيرُكَ', 1, 'ما يقول بعد تكبيرة الإحرام ويُسمَّى دعاء الاستفتاح (أو التوجُّه). (ص93)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (910, 10, 4, 'اللهُ أكبرُ كبيرًا، والحمدُ للهِ كثيرًا، وسبحانَ اللهِ بُكرةً وأصيلًا', 1, 'ما يقول بعد تكبيرة الإحرام ويُسمَّى دعاء الاستفتاح (أو التوجُّه). (ص93)', '', '', 'الله أكبر كبيرا والحمد لله كثيرا وسبحان الله بكرة وأصيلا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (911, 10, 5, 'الحمدُ للهِ حمدًا كثيرًا طَيِّبًا مبارَكًا فيه', 1, 'ما يقول بعد تكبيرة الإحرام ويُسمَّى دعاء الاستفتاح (أو التوجُّه). (ص93)', '', '', 'الحمد لله حمدا كثيرا طيبا مباركا فيه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (912, 10, 6, 'اللهم لك الحمدُ، أنت نورُ السماواتِ والأرضِ وَمَنْ فيهنَّ، ولك الحمدُ، أنت قَيِّمُ السماواتِ والأرضِ وَمَنْ فيهنَّ، ولك الحمدُ، أنتَ مَلِكُ السماواتِ والأرضِ وَمَنْ فيهن، ولك الحمدُ، أنتَ الحقُّ، ووعدُك الحقُّ، وقولُك حقٌّ، ولقاؤُك حقٌّ، والجنَّةُ حقٌّ، والنَّارُ حقٌّ، والساعةُ حقٌّ، والنبيُّون حقٌّ، ومحمدٌ حقٌّ، اللهم لك أسلمتُ، وعليك توكلتُ، وبك آمنتُ، وإليك أنَبْتُ، وبك خَاصَمْتُ، وإليك حاكمتُ، أنت رَبُّنا، وإليكَ المصير، فاغفر لي ما قَدَّمْتُ، وما أخَّرتُ، وما أسررتُ، وما أعلنتُ، وما أنت أعلمُ به مني، أنت المقدِّمُ، وأنت المؤخِّرُ، أنت إلهي، لاَ إله إلا أنت، ولا حول ولا قوة إلا بك', 1, 'دعاء الاستفتاح في التهجُّد. (ص94)', '', '', 'اللهم لك الحمد أنت نور السماوات والأرض ومن فيهن ولك الحمد أنت قيم السماوات والأرض ومن فيهن ولك الحمد أنت ملك السماوات والأرض ومن فيهن ولك الحمد أنت الحق ووعدك الحق وقولك حق ولقاؤك حق والجنة حق والنار حق والساعة حق والنبيون حق ومحمد حق اللهم لك أسلمت وعليك توكلت وبك آمنت وإليك أنبت وبك خاصمت وإليك حاكمت أنت ربنا وإليك المصير فاغفر لي ما قدمت وما أخرت وما أسررت وما أعلنت وما أنت أعلم به مني أنت المقدم وأنت المؤخر أنت إلهي لا إله إلا أنت ولا حول ولا قوة إلا بك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (913, 10, 7, 'اللهمَّ ربَّ جبرائيلَ وميكائيلَ وإسرافيلَ، فاطرَ السماواتِ والأرضِ، عالمَ الغيبِ والشهادةِ، أنت تحكُمُ بين عبادك فيما كانوا فيه يختلفون؛ اهدِني لما اخْتُلِفَ فيه من الحقِّ بإذنك، إنك تهدي من تشاءُ إلى صراطٍ مُستقيمٍ', 1, 'دعاء الاستفتاح في التهجُّد. (ص94–95)', '', '', 'اللهم رب جبرائيل وميكائيل وإسرافيل فاطر السماوات والأرض عالم الغيب والشهادة أنت تحكم بين عبادك فيما كانوا فيه يختلفون اهدني لما اختلف فيه من الحق بإذنك إنك تهدي من تشاء إلى صراط مستقيم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (914, 10, 8, 'اللهُ أكبرُ', 10, 'دعاء الاستفتاح في التهجُّد. [عشرًا]. (ص95)', '', '', 'الله أكبر', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1205, 10, 9, 'الحمدُ للهِ', 10, 'دعاء الاستفتاح في التهجُّد. [عشرًا]. (ص95)', '', '', 'الحمد لله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1206, 10, 10, 'سبحانَ اللهِ', 10, 'دعاء الاستفتاح في التهجُّد. [عشرًا]. (ص95)', '', '', 'سبحان الله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1207, 10, 11, 'لا إله إلا اللهُ', 10, 'دعاء الاستفتاح في التهجُّد. [عشرًا]. (ص95)', '', '', 'لا إله إلا الله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1208, 10, 12, 'أستغفرُ اللهَ', 10, 'دعاء الاستفتاح في التهجُّد. [عشرًا]. (ص95)', '', '', 'أستغفر الله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1209, 10, 13, 'اللهم اغفر لي، واهدني، وارزقني، وعافني', 10, 'دعاء الاستفتاح في التهجُّد. [عشرًا]. (ص95)', '', '', 'اللهم اغفر لي واهدني وارزقني وعافني', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1210, 10, 14, 'اللهم إني أعوذ بك من الضيق يوم الحساب', 10, 'دعاء الاستفتاح في التهجُّد. [عشرًا]. (ص95)', '', '', 'اللهم إني أعوذ بك من الضيق يوم الحساب', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (915, 10, 15, 'اللهُ أكبرُ، اللهُ أكبرُ ذو المَلَكُوتِ والجَبَرُوتِ والكبرياءِ والعَظَمَةِ', 1, 'دعاء الاستفتاح في التهجُّد. (ص95)', '', '', 'الله أكبر الله أكبر ذو الملكوت والجبروت والكبرياء والعظمة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (916, 10, 16, 'سبحانَك اللهمَّ وبحمدِكَ، وتبارك اسمُكَ، وتعالى جَدُّكَ، ولا إله غيرُكَ', 1, 'دعاء الاستفتاح في التهجُّد. (ص96)', '', '', 'سبحانك اللهم وبحمدك وتبارك اسمك وتعالى جدك ولا إله غيرك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1211, 10, 17, 'لا إله إلا اللهُ', 3, 'دعاء الاستفتاح في التهجُّد. [ثلاثًا]. (ص96)', '', '', 'لا إله إلا الله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1212, 10, 18, 'اللهُ أكبرُ كبيرًا', 3, 'دعاء الاستفتاح في التهجُّد. [ثلاثًا]. (ص96)', '', '', 'الله أكبر كبيرا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1213, 10, 19, 'إذا أراد القراءة قال:', 0, 'التعوُّذ بعد دعاء الاستفتاح. (ص96)', '', '', 'إذا أراد القراءة قال', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (917, 10, 20, 'أعوذُ باللهِ من الشيطانِ الرجيم', 1, 'التعوُّذ بعد دعاء الاستفتاح. (ص96)', '', '', 'أعوذ بالله من الشيطان الرجيم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (918, 10, 21, 'أو: أعوذ بالله من الشيطانِ الرجيم من هَمْزِه ونَفْخِه ونَفْثِه', 1, 'التعوُّذ بعد دعاء الاستفتاح. (ص96)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (919, 10, 22, 'أو: أعوذ بالله السميع العليم من الشيطانِ الرجيمِ، من هَمْزِه ونَفْخِه ونِفْثِه', 1, 'التعوُّذ بعد دعاء الاستفتاح. (ص96)', '', '', 'أو أعوذ بالله السميع العليم من الشيطان الرجيم من همزه ونفخه ونفثه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (920, 11, 1, 'سبحانَ رَبِّيَ العظيمِ', 3, 'أذكار الركوع. [ثلاثًا أو أكثر]. (ص97)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (921, 11, 2, 'سبحانَ رَبِّيَ العظيمِ وبحمدِهِ', 3, 'أذكار الركوع. [ثلاثًا]. (ص97)', '', '', 'سبحان ربي العظيم وبحمده', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (922, 11, 3, 'سبحانَكَ اللهم ربَّنا وبحمدِكَ، اللهم اغفر لي', 1, 'أذكار الركوع. (ص97)', '', '', 'سبحانك اللهم ربنا وبحمدك اللهم اغفر لي', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (923, 11, 4, 'سبحانَكَ اللهم وبحمدِكَ، لا إله إلا أنت', 1, 'أذكار الركوع. (ص97)', '', '', 'سبحانك اللهم وبحمدك لا إله إلا أنت', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (924, 11, 5, 'سُبُّوحٌ قُدُّوسٌ، ربُّ الملائكةِ والرُّوحِ', 1, 'أذكار الركوع. (ص97)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (925, 11, 6, 'سبحانَ ذي الجبروتِ والملكوتِ، والكبرياءِ والعظمةِ', 1, 'أذكار الركوع. (ص98)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (926, 11, 7, 'اللهم لك ركعتُ، وبك آمنتُ، ولك أسلمتُ، أنت رَبِّي، خَشَعَ لَكَ سَمْعِي وبَصَرِي، ومُخِّي وعَظْمي وعَصَبِي، وما استَقَلَّتْ به قَدَمِي للهِ رَبِّ العالمين', 1, 'أذكار الركوع. (ص98)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (927, 11, 8, 'اللهم لك ركعتُ، وبك آمنتُ، ولك أسلمتُ، وعليك توكلتُ، أنت ربي، خَشَعَ سمعي وبصري، ودمي ولحمي، وعَظْمي وعَصَبِي للهِ رَبِّ العالمين', 1, 'أذكار الركوع. (ص98)', '', '', 'اللهم لك ركعت وبك آمنت ولك أسلمت وعليك توكلت أنت ربي خشع سمعي وبصري ودمي ولحمي وعظمي وعصبي لله رب العالمين', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1214, 11, 9, 'يقول حالَ رفع رأسِه:', 0, 'ما يقول في رفع رأسه من الركوع وفي اعتداله. (ص99)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (928, 11, 10, 'سَمِعَ اللهُ لمن حَمِدَه', 1, 'ما يقول في رفع رأسه من الركوع وفي اعتداله. (ص99)', '', '', 'سمع الله لمن حمده', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1215, 11, 11, 'فإذا استوى قائمًا قال:', 0, 'ما يقول في رفع رأسه من الركوع وفي اعتداله. (ص99)', '', '', 'فإذا استوى قائما قال', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (929, 11, 12, 'رَبَّنا لكَ الحمدُ، أو: ربنا ولك الحمدُ', 1, 'ما يقول في رفع رأسه من الركوع وفي اعتداله. (ص99)', '', '', 'ربنا لك الحمد أو ربنا ولك الحمد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (931, 11, 13, 'أو: اللهم رَبَّنا ولكَ الحمدُ', 1, 'ما يقول في رفع رأسه من الركوع وفي اعتداله. (ص99)', '', '', 'أو اللهم ربنا ولك الحمد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (932, 11, 14, 'أو: رَبَّنا ولك الحمدُ، حمدًا كثيرًا طيبًا مُبَارَكًا فيه، مباركًا عليه، كما يُحِبُّ رَبُّنا ويرضى', 1, 'ما يقول في رفع رأسه من الركوع وفي اعتداله. (ص99)', '', '', 'أو ربنا ولك الحمد حمدا كثيرا طيبا مباركا فيه مباركا عليه كما يحب ربنا ويرضى', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (933, 11, 15, 'أو: رَبَّنا لك الحمدُ، مِلْءَ السماواتِ، ومِلْءَ الأرضِ، وملءَ ما بينهما، وملءَ ما شِئْتَ مِنْ شيءٍ بَعْدُ، أهلَ الثناءِ والمجدِ، أحقُّ ما قال العبدُ، وكلُّنا لك عبدٌ، اللهم لا مانعَ لما أعطيتَ، ولا مُعْطِيَ لما منعتَ، ولا ينفعُ ذا الجَدِّ منك الجَدُّ', 1, 'ما يقول في رفع رأسه من الركوع وفي اعتداله. (ص99–100)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (934, 11, 16, 'اللهم لك الحمدُ، مِلْءَ السماواتِ، ومِلْءَ الأرضِ، ومِلْءَ ما شِئْتَ مِنْ شيءٍ بَعْدُ، اللهم طَهِّرْني بالثلجِ والبَرَدِ والماءِ البارد، اللهم طَهِّرْني من الذنوبِ والخطايا كما يُنَقَّى الثوبُ الأبيضُ من الدَّنَسِ', 1, 'ما يقول في رفع رأسه من الركوع وفي اعتداله. (ص100)', '', '', 'اللهم لك الحمد ملء السماوات وملء الأرض وملء ما شئت من شيء بعد اللهم طهرني بالثلج والبرد والماء البارد اللهم طهرني من الذنوب والخطايا كما ينقى الثوب الأبيض من الدنس', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (935, 11, 17, 'أو يقول: «لِرَبِّيَ الحمدُ، لِرَبِّيَ الحمدُ»، ويُكْرِرها في قيام الليل طويلًا', 1, 'ما يقول في رفع رأسه من الركوع وفي اعتداله. (ص100)', '', '', 'أو يقول لربي الحمد لربي الحمد ويكررها في قيام الليل طويلا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (103, 12, 1, 'سبحانَ رَبِّيَ الأعلى', 3, 'أذكار السجود. [ثلاثًا، أو أكثر إذا أراد التطويل]. (ص100)', '', '', 'سبحان ربي الأعلى', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (104, 12, 2, 'سبحانَ رَبِّيَ الأعلى وبحمدِه', 3, 'أذكار السجود. [ثلاثًا]. (ص100)', '', '', 'سبحان ربي الأعلى وبحمده', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (105, 12, 3, 'سبحانَكَ اللهم رَبَّنا وبحمدِكَ، اللهم اغفرْ لي', 1, 'أذكار السجود. (ص100)', '', '', 'سبحانك اللهم ربنا وبحمدك اللهم اغفر لي', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (106, 12, 4, 'سُبُّوحٌ قُدُّوسٌ، رَبُّ الملائكةِ والرُّوحِ', 1, 'أذكار السجود. (ص100)', '', '', 'سبوح قدوس رب الملائكة والروح', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (107, 12, 5, 'سبحانَ ذي الجَبَروتِ والمَلَكوتِ، والكبرياءِ والعَظَمةِ', 1, 'أذكار السجود. (ص101)', '', '', 'سبحان ذي الجبروت والملكوت والكبرياء والعظمة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (108, 12, 6, 'اللهم اغفرْ لي ما أسررتُ، وما أعلنتُ', 1, 'أذكار السجود. (ص101)', '', '', 'اللهم اغفر لي ما أسررت وما أعلنت', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (109, 12, 7, 'اللهم اغفرْ لي ذنبي كُلَّه، ودِقَّه وجِلَّه، وأوَّلَه وآخِرَه، وعلانِيَتَه وسِرَّه', 1, 'أذكار السجود. (ص101)', '', '', 'اللهم اغفر لي ذنبي كله ودقه وجله وأوله وآخره وعلانيته وسره', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (110, 12, 8, 'اللهم إني أعوذُ برِضاكَ من سَخَطِكَ، وأعوذُ بمعافاتِكَ من عقوبتِكَ، وأعوذُ بك منك، لا أُحصي ثناءً عليك، أنتَ كما أثنيتَ على نفسِكَ', 1, 'أذكار السجود. (ص101)', '', '', 'اللهم إني أعوذ برضاك من سخطك وأعوذ بمعافاتك من عقوبتك وأعوذ بك منك لا أحصي ثناء عليك أنت كما أثنيت على نفسك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (111, 12, 9, 'اللهم إني ظلمتُ نفسي ظُلمًا كثيرًا، ولا يغفرُ الذنوبَ إلا أنتَ، فاغفرْ لي مغفرةً مِن عندك، وارحمني إنك أنت الغفورُ الرحيم', 1, 'أذكار السجود. (ص101)', '', '', 'اللهم إني ظلمت نفسي ظلما كثيرا ولا يغفر الذنوب إلا أنت فاغفر لي مغفرة من عندك وارحمني إنك أنت الغفور الرحيم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (112, 12, 10, 'اللهم لك سجدتُ، وبك آمنتُ، ولك أسلمتُ، وأنت ربي، سجدَ وجهي لِلَّذي خَلَقَهُ وصَوَّرَهُ، فأحسنَ صُوَرَه، وشَقَّ سَمْعَهُ وبَصَرَهُ، فتباركَ اللهُ أحسنُ الخالقين', 1, 'أذكار السجود. (ص101)', '', '', 'اللهم لك سجدت وبك آمنت ولك أسلمت وأنت ربي سجد وجهي للذي خلقه وصوره فأحسن صوره وشق سمعه وبصره فتبارك الله أحسن الخالقين', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (113, 12, 11, 'سَجَدَ لك سَوادي وخيالي، وآمَنَ بك فؤادي، أبوءُ بنعمتِكَ عَلَيَّ، هَذِي يَدِي، وما جَنَيْتُ على نفسي', 1, 'أذكار السجود. (ص102)', '', '', 'سجد لك سوادي وخيالي وآمن بك فؤادي أبوء بنعمتك علي هذي يدي وما جنيت على نفسي', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (114, 12, 12, 'اللهم اجعل في قلبي نورًا، وفي لساني نورًا، واجعل في سمعي نورًا، واجعل في بصري نورًا، واجعل مِن تحتي نورًا، واجعل مِن فوقي نورًا، وعن يميني نورًا، وعن يساري نورًا، واجعل أمامي نورًا، واجعل خلفي نورًا، واجعل في نفسي نورًا، وأعظِمْ لي نورًا', 1, 'أذكار السجود. (ص102)', '', '', 'اللهم اجعل في قلبي نورا وفي لساني نورا واجعل في سمعي نورا واجعل في بصري نورا واجعل من تحتي نورا واجعل من فوقي نورا وعن يميني نورا وعن يساري نورا واجعل أمامي نورا واجعل خلفي نورا واجعل في نفسي نورا وأعظم لي نورا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (115, 12, 13, 'سبحانك اللهم وبحمدك، لا إله إلا أنت', 1, 'أذكار السجود. (ص102)', '', '', 'سبحانك اللهم وبحمدك لا إله إلا أنت', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1216, 12, 14, 'وكان صلى الله عليه وسلم يقول: «أقرَبُ ما يكونُ العبدُ من رَبِّه وهُوَ ساجدٌ، فأكثِروا الدعاءَ فيه».', 0, 'أذكار السجود. (ص102)', '', '', 'وكان صلى الله عليه وسلم يقول أقرب ما يكون العبد من ربه وهو ساجد فأكثروا الدعاء فيه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (116, 13, 1, 'رَبِّ اغفِرْ لي، رَبِّ اغفِرْ لي', 1, 'ما يقول بين السجدتين. (ص102)', '', '', 'رب اغفر لي رب اغفر لي', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (117, 13, 2, 'اللهم اغفر لي، وارحمني، واجْبُرْنِي، وارْفَعْنِي، واهْدِنِي، وعافِنِي، وارزقني', 1, 'ما يقول بين السجدتين. (ص102)', '', '', 'اللهم اغفر لي وارحمني واجبرني وارفعني واهدني وعافني وارزقني', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1217, 13, 3, 'يدعو بمثل دعائه في سجود الصلاة. ويقول أيضًا:', 0, 'دعاء سجدة التلاوة. (ص103)', '', '', 'يدعو بمثل دعائه في سجود الصلاة ويقول أيضا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (118, 13, 4, 'سَجَدَ وجهي لِلَّذي خَلَقَهُ، وشَقَّ سمعَه وبَصَرَه بحوله وقُوَّتِه', 1, 'دعاء سجدة التلاوة. (ص103)', '', '', 'سجد وجهي للذي خلقه وشق سمعه وبصره بحوله وقوته', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (119, 13, 5, 'اللَّهُمَّ اكتُبْ لي بها عِنْدَكَ أجرًا، وَضَعْ عنِّي بها وِزْرًا، واجعَلْها لي عِندَكَ ذُخرًا، وَتَقَبَّلْها مِنِّي كما تَقَبَّلْتَها من عَبْدِكَ داودَ', 1, 'دعاء سجدة التلاوة. (ص103)', '', '', 'اللهم اكتب لي بها عندك أجرا وضع عني بها وزرا واجعلها لي عندك ذخرا وتقبلها مني كما تقبلتها من عبدك داود', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1218, 17, 1, 'ومحلُّه بعد قوله: «سمع الله لمن حمده، ربنا لك الحمد»، فيجهرُ بدعائه، ويرفع يديه، ويدعو بما رواه الحَسَنُ بْنُ عَلِيٍّ رضي الله عنهما مرفوعًا:', 0, 'قنوت الوتر في رمضان وغيره. (ص103)', '', '', 'ومحله بعد قوله سمع الله لمن حمده ربنا لك الحمد فيجهر بدعائه ويرفع يديه ويدعو بما رواه الحسن بن علي رضي الله عنهما مرفوعا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (153, 17, 2, 'اللهم اهدِني فيمن هديتَ، وعافِني فيمن عافيتَ، وتولَّني فيمن توليتَ، وباركْ لي فيما أعطيتَ، وقِني شرَّ ما قضيتَ، فإنَّكَ تقضي ولا يُقضى عليك، وإنه لا يَذِلُّ من واليتَ، ولا يَعِزُّ من عاديتَ، تباركتَ ربَّنا وتعاليتَ، لا مَنْجا منكَ إلا إليك', 1, 'قنوت الوتر في رمضان وغيره. (ص103–104)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1219, 17, 3, 'وصَحَّ أنَّ الصحابة رضي الله عنهم كانوا يَزيدون عليه في النصف الثاني من رمضان، ومن ذلك دعاء عمر رضي الله عنه:', 0, 'قنوت الوتر في رمضان وغيره. (ص104)', '', '', 'وصح أن الصحابة رضي الله عنهم كانوا يزيدون عليه في النصف الثاني من رمضان ومن ذلك دعاء عمر رضي الله عنه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (155, 17, 4, '«اللهمَّ إنَّا نستعينُكَ ونستغفرُكَ، ولا نَكْفُرُكَ، ونُؤمِنُ بِكَ، ونخلعُ مَنْ يَفْجُرُكَ، اللهمَّ إيَّاكَ نعبدُ، ولك نُصَلِّي ونَسْجُدُ، وإليكَ نسعى ونَحْفِدُ، نرجو رحمتَكَ، ونخشى عذابَكَ، إنَّ عذابَكَ الجِدَّ بالكُفَّارِ مُلْحِقٌ', 1, 'قنوت الوتر في رمضان وغيره. (ص104)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (154, 17, 5, 'اللهمَّ عَذِّبِ الكَفَرَةَ الَّذين يَصُدُّون عن سبيلِكَ، ويُكَذِّبون رُسُلَكَ، ويُقاتلون أولياءَكَ، ولا يُؤْمنون بوعدِكَ، وخالِفْ بَيْنَ كَلِمَتِهم، وأَلْقِ في قلوبهم الرُّعبَ، وأَلْقِ عليهم رِجْزَكَ وعذابَكَ، إلهَ الحقِّ', 1, 'قنوت الوتر في رمضان وغيره. (ص104–105)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1220, 17, 6, 'اللهمَّ اغفِرْ للمؤمنين والمؤمنات، والمسلمين والمسلمات، وأَصْلِحْ ذاتَ بَيْنِهم، وأَلِّفْ بَيْنَ قلوبهم، واجعَلْ في قلوبهم الإيمانَ والحكمةَ، وثَبِّتْهم على مِلَّةِ رَسُولِ اللهِ صلى الله عليه وسلم، وأَوْزِعْهم أن يُوفُوا بعهدِكَ الذي عاهدتَهم عليه، وانصُرْهم على عَدُوِّكَ وعَدُوِّهم، إلهَ الحقِّ، واجعلنا منهم»', 1, 'قنوت الوتر في رمضان وغيره. (ص105)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (156, 17, 7, 'ويُشْرَعُ القنوتُ في الصلوات الخمس للنازلة، فيدعو لقومٍ، أو يدعو على قوم.', 0, 'قنوت الوتر في رمضان وغيره. (ص105)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1221, 14, 1, 'يقول إحدى الصِّيَغ الآتية:', 0, 'التشهد في الصلاة. (ص106)', '', '', 'يقول إحدى الصيغ الآتية', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (120, 14, 2, 'التحياتُ للهِ، والصلواتُ والطيباتُ، السلامُ عليكَ أيها النبيُّ ورحمةُ اللهِ وبركاتُه، السلامُ علينا وعلى عبادِ اللهِ الصالحين، أشهدُ أن لا إله إلا اللهُ، وأشهدُ أن محمدًا عبدُه ورسولُه', 1, 'التشهد في الصلاة. (ص106–107)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (936, 14, 3, 'التحياتُ المباركاتُ الصلواتُ الطيباتُ للهِ، السلامُ عليكَ أيها النبيُّ ورحمةُ اللهِ وبركاتُه، السلامُ علينا وعلى عبادِ اللهِ الصالحين، أشهدُ أن لا إله إلا اللهُ، وأشهدُ أن محمدًا رسولُ اللهِ', 1, 'التشهد في الصلاة. (ص107)', '', '', 'التحيات المباركات الصلوات الطيبات لله السلام عليك أيها النبي ورحمة الله وبركاته السلام علينا وعلى عباد الله الصالحين أشهد أن لا إله إلا الله وأشهد أن محمدا رسول الله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1222, 14, 4, 'وفي روايةٍ: «عبدُه ورسولُه».', 0, 'التشهد في الصلاة. (ص107)', '', '', 'وفي رواية عبده ورسوله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (937, 14, 5, 'التحياتُ للهِ، والصلواتُ والطيباتُ، السلامُ عليكَ أيها النبيُّ ورحمةُ اللهِ وبركاتُه، السلامُ علينا وعلى عبادِ اللهِ الصالحين، أشهدُ أنْ لا إله إلا اللهُ وحدَه لا شريكَ له، وأشهدُ أنَّ محمدًا عبدُه ورسولُه', 1, 'التشهد في الصلاة. (ص107)', '', '', 'التحيات لله والصلوات والطيبات السلام عليك أيها النبي ورحمة الله وبركاته السلام علينا وعلى عباد الله الصالحين أشهد أن لا إله إلا الله وحده لا شريك له وأشهد أن محمدا عبده ورسوله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (938, 14, 6, 'التحياتُ الطيباتُ الصلواتُ للهِ، السلامُ عليكَ أيها النبيُّ ورحمةُ اللهِ وبركاتُه، السلامُ علينا وعلى عبادِ اللهِ الصالحين، أشهدُ أنْ لا إله إلا اللهُ وحدَه لا شريكَ له، وأشهدُ أنَّ محمدًا عبدُه ورسولُه', 1, 'التشهد في الصلاة. (ص107)', '', '', 'التحيات الطيبات الصلوات لله السلام عليك أيها النبي ورحمة الله وبركاته السلام علينا وعلى عباد الله الصالحين أشهد أن لا إله إلا الله وحده لا شريك له وأشهد أن محمدا عبده ورسوله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (939, 14, 7, 'التحياتُ للهِ، الزاكياتُ للهِ، الطيباتُ للهِ، الصلواتُ للهِ، السلامُ عليكَ أيها النبيُّ ورحمةُ اللهِ وبركاتُه، السلامُ علينا وعلى عبادِ اللهِ الصالحين، أشهدُ أن لا إله إلا اللهُ، وأشهدُ أن محمدًا عبدُه ورسولُه', 1, 'التشهد في الصلاة. (ص108)', '', '', 'التحيات لله الزاكيات لله الطيبات لله الصلوات لله السلام عليك أيها النبي ورحمة الله وبركاته السلام علينا وعلى عباد الله الصالحين أشهد أن لا إله إلا الله وأشهد أن محمدا عبده ورسوله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1223, 14, 8, 'يقول إحدى الصِّيَغ الآتية:', 0, 'الصلاة على النبي صلى الله عليه وسلم بعد التشهد. (ص109)', '', '', 'يقول إحدى الصيغ الآتية', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (121, 14, 9, 'اللهمَّ صلِّ على محمدٍ وعلى آلِ محمدٍ، كما صليتَ على إبراهيمَ وعلى آلِ إبراهيمَ، إنَّكَ حميدٌ مجيدٌ، اللهمَّ باركْ على محمدٍ وعلى آلِ محمدٍ، كما باركتَ على إبراهيمَ وعلى آلِ إبراهيمَ، إنَّكَ حميدٌ مجيدٌ', 1, 'الصلاة على النبي صلى الله عليه وسلم بعد التشهد. (ص109)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (940, 14, 10, 'اللهمَّ صلِّ على محمدٍ وعلى أهلِ بيتِه، وعلى أزواجِه وذُرِّيَّتِه، كما صليتَ على آلِ إبراهيمَ، إنَّكَ حميدٌ مجيدٌ، وبارِكْ على محمدٍ وعلى آلِ بيتِه، وعلى أزواجِه وذريتِه، كما باركتَ على آلِ إبراهيمَ، إنَّكَ حميدٌ مجيدٌ', 1, 'الصلاة على النبي صلى الله عليه وسلم بعد التشهد. (ص110)', '', '', 'اللهم صل على محمد وعلى أهل بيته وعلى أزواجه وذريته كما صليت على آل إبراهيم إنك حميد مجيد وبارك على محمد وعلى آل بيته وعلى أزواجه وذريته كما باركت على آل إبراهيم إنك حميد مجيد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (941, 14, 11, 'اللهمَّ صلِّ على محمدٍ، وعلى آلِ محمدٍ، كما صَلَّيتَ على إبراهيمَ وآلِ إبراهيمَ، إنَّكَ حميدٌ مجيدٌ، وبارِكْ على محمدٍ، وعلى آلِ محمدٍ، كما باركتَ على إبراهيمَ وآلِ إبراهيمَ، إنَّكَ حميدٌ مجيدٌ', 1, 'الصلاة على النبي صلى الله عليه وسلم بعد التشهد. (ص110)', '', '', 'اللهم صل على محمد وعلى آل محمد كما صليت على إبراهيم وآل إبراهيم إنك حميد مجيد وبارك على محمد وعلى آل محمد كما باركت على إبراهيم وآل إبراهيم إنك حميد مجيد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (942, 14, 12, 'اللَّهُمَّ صَلِّ على مُحَمَّدٍ النَّبِيِّ الأُمِّيِّ، وعلى آلِ محمدٍ، كما صَلَّيْتَ على آلِ إبراهيمَ، وبارِكْ على محمدٍ النَّبِيِّ الأُمِّيِّ، وعلى آلِ محمدٍ، كما باركتَ على آلِ إبراهيمَ في العالمينَ، إنَّكَ حَمِيدٌ مَجِيدٌ', 1, 'الصلاة على النبي صلى الله عليه وسلم بعد التشهد. (ص110)', '', '', 'اللهم صل على محمد النبي الأمي وعلى آل محمد كما صليت على آل إبراهيم وبارك على محمد النبي الأمي وعلى آل محمد كما باركت على آل إبراهيم في العالمين إنك حميد مجيد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (943, 14, 13, 'اللَّهُمَّ صَلِّ على محمدٍ عبدِكَ ورسولِكَ، كما صَلَّيْتَ على آلِ إبراهيمَ، وبارِكْ على محمدٍ عبدِكَ ورسولِكَ، وعلى آلِ محمدٍ، كما باركْتَ على إبراهيمَ، وعلى آلِ إبراهيمَ', 1, 'الصلاة على النبي صلى الله عليه وسلم بعد التشهد. (ص110)', '', '', 'اللهم صل على محمد عبدك ورسولك كما صليت على آل إبراهيم وبارك على محمد عبدك ورسولك وعلى آل محمد كما باركت على إبراهيم وعلى آل إبراهيم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (122, 14, 14, 'اللهم صَلِّ على محمدٍ وعلى أزواجِهِ وذُرِّيَّتِهِ، كما صَلَّيْتَ على آلِ إبراهيمَ، وبارِكْ على محمدٍ وعلى أزواجِهِ وذريتِهِ، كما باركتَ على آلِ إبراهيمَ، إنَّكَ حميدٌ مجيدٌ', 1, 'الصلاة على النبي صلى الله عليه وسلم بعد التشهد. (ص111)', '', '', 'اللهم صل على محمد وعلى أزواجه وذريته كما صليت على آل إبراهيم وبارك على محمد وعلى أزواجه وذريته كما باركت على آل إبراهيم إنك حميد مجيد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (944, 14, 15, 'اللهم صَلِّ على محمدٍ، وعلى آلِ محمدٍ، وبارِكْ على محمدٍ، وعلى آلِ محمدٍ، كما صَلَّيْتَ وباركتَ على إبراهيمَ وآلِ إبراهيمَ، إنَّكَ حَميدٌ مجيدٌ', 1, 'الصلاة على النبي صلى الله عليه وسلم بعد التشهد. (ص111)', '', '', 'اللهم صل على محمد وعلى آل محمد وبارك على محمد وعلى آل محمد كما صليت وباركت على إبراهيم وآل إبراهيم إنك حميد مجيد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1224, 15, 1, 'إذا فرغ من التشهد الأخير، قال:', 0, 'الدعاء بعد التشهُّد الأخير. (ص112)', '', '', 'إذا فرغ من التشهد الأخير قال', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (123, 15, 2, 'اللهم إنِّي أعوذُ بك من عذابِ جَهَنَّمَ، ومن عذابِ القبرِ، ومن فتنةِ المحيا والمماتِ، ومن شَرِّ فتنةِ المسيحِ الدَّجَّالِ', 1, 'الدعاء بعد التشهُّد الأخير. (ص112)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1225, 15, 3, 'ثم يتخيَّرُ من الأدعية المأثورة في هذا الموضع أعجَبَهُ إليه، ومنها:', 0, 'الدعاء بعد التشهُّد الأخير. (ص112)', '', '', 'ثم يتخير من الأدعية المأثورة في هذا الموضع أعجبه إليه ومنها', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (124, 15, 4, 'اللهم إني أعوذُ بك من عذابِ القبرِ، وأعوذُ بك من فتنةِ المسيحِ الدجالِ، وأعوذُ بك من فتنةِ المحيا والمماتِ، اللهم إنِّي أعوذُ بك من المأثَمِ والمغرَم', 1, 'الدعاء بعد التشهُّد الأخير. (ص112)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (125, 15, 5, 'اللهم إني أعوذُ بك من شَرِّ ما عَمِلْتُ، ومن شر ما لم أعمل', 1, 'الدعاء بعد التشهُّد الأخير. (ص113)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (126, 15, 6, 'اللهم إني أسألُكَ الجنَّةَ، وأعوذُ بك من النَّارِ', 1, 'الدعاء بعد التشهُّد الأخير. (ص113)', '', '', 'اللهم إني أسألك الجنة وأعوذ بك من النار', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (127, 15, 7, 'اللهم إني ظلمتُ نفسي ظُلْمًا كثيرًا، ولا يغفرُ الذنوبَ إلَّا أنتَ، فاغفرْ لي مغفرةً مِن عِندِك، وارْحَمْني إنك أنتَ الغفورُ الرحيمُ', 1, 'الدعاء بعد التشهُّد الأخير. (ص113)', '', '', 'اللهم إني ظلمت نفسي ظلما كثيرا ولا يغفر الذنوب إلا أنت فاغفر لي مغفرة من عندك وارحمني إنك أنت الغفور الرحيم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (128, 15, 8, 'اللهم حاسِبْني حسابًا يسيرًا', 1, 'الدعاء بعد التشهُّد الأخير. (ص113)', '', '', 'اللهم حاسبني حسابا يسيرا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (129, 15, 9, 'اللهم إني أسألُكَ يا اللهُ الواحدُ الأحدُ الصَّمَدُ، الذي لم يَلِدْ ولَمْ يُولَدْ، ولَمْ يَكُنْ له كُفُوًا أحدٌ، أن تَغْفِرَ لي ذُنُوبي، إنَّكَ أنتَ الغفورُ الرَّحيمُ', 1, 'الدعاء بعد التشهُّد الأخير. (ص113)', '', '', 'اللهم إني أسألك يا الله الواحد الأحد الصمد الذي لم يلد ولم يولد ولم يكن له كفوا أحد أن تغفر لي ذنوبي إنك أنت الغفور الرحيم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (130, 15, 10, 'اللهم إنِّي أسألُكَ بأنَّ لَكَ الحمدَ، لا إلهَ إلَّا أنتَ وحدَكَ، لا شريكَ لك، المنَّانُ، يا بديعَ السَّماواتِ والأرضِ، يا ذا الجلالِ والإكرامِ، يا حَيُّ يا قَيُّومُ، إنِّي أسألُكَ الجَنَّةَ، وأعوذُ بكَ من النَّارِ', 1, 'الدعاء بعد التشهُّد الأخير. (ص114)', '', '', 'اللهم إني أسألك بأن لك الحمد لا إله إلا أنت وحدك لا شريك لك المنان يا بديع السماوات والأرض يا ذا الجلال والإكرام يا حي يا قيوم إني أسألك الجنة وأعوذ بك من النار', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (131, 15, 11, 'اللهم إنِّي أسألُكَ من الخيرِ كُلِّه، عاجِلِه وآجِلِه، ما عَلِمْتُ منه وما لم أعلمْ، وأعوذُ بك من الشَّرِّ كُلِّه، عاجِلِه وآجِلِه، ما عَلِمْتُ منه وما لَمْ أعلمْ، اللهم إنِّي أسألُكَ الجَنَّةَ، وما قَرَّبَ إليها مِنْ قَوْلٍ أو عَمَلٍ، وأعوذُ بكَ من النَّارِ، وما قَرَّبَ إليها من قولٍ أو عملٍ، اللهم إنِّي أسألُكَ من خيرِ ما سألَكَ عبدُكَ ورسولُكَ محمدٌ صلى الله عليه وسلم، وأعوذُ بكَ من شَرِّ ما استعاذَكَ منه عبدُكَ ورسولُكَ محمدٌ صلى الله عليه وسلم، وأسألُكَ ما قَضَيْتَ لي مِنْ أمرٍ أن تجعلَ عاقِبَتَهُ لي رَشَدًا', 1, 'الدعاء بعد التشهُّد الأخير. (ص114)', '', '', 'اللهم إني أسألك من الخير كله عاجله وآجله ما علمت منه وما لم أعلم وأعوذ بك من الشر كله عاجله وآجله ما علمت منه وما لم أعلم اللهم إني أسألك الجنة وما قرب إليها من قول أو عمل وأعوذ بك من النار وما قرب إليها من قول أو عمل اللهم إني أسألك من خير ما سألك عبدك ورسولك محمد صلى الله عليه وسلم وأعوذ بك من شر ما استعاذك منه عبدك ورسولك محمد صلى الله عليه وسلم وأسألك ما قضيت لي من أمر أن تجعل عاقبته لي رشدا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (132, 15, 12, 'اللهم بِعِلْمِكَ الغيبَ، وقُدْرَتِكَ على الخَلْقِ، أَحْيِني ما علمتَ الحياةَ خيرًا لي، وتَوَفَّني إذا كانتِ الوفاةُ خيرًا لي، اللهم وأسألُكَ خشيتَكَ في الغيبِ والشهادةِ، وأسألُكَ كلمةَ الحقِّ والعدلِ في الغضبِ والرِّضَى، وأسألُكَ القصدَ في الفقرِ والغِنَى، وأسألُكَ نعيمًا لا يَبِيدُ، وأسألُكَ قُرَّةَ عينٍ لا تنفدُ، ولا تنقطعُ، وأسألُكَ الرِّضا بعد القضاءِ، وأسألُكَ بَرْدَ العيشِ بعد الموتِ، وأسألُكَ لَذَّةَ النَّظَرِ إلى وَجْهِكَ، وأسألُكَ الشوقَ إلى لقائِكَ، في غيرِ ضَرَّاءَ مُضِرَّةٍ، ولا فِتْنَةٍ مُضِلَّةٍ، اللهم زَيِّنَّا بزينةِ الإيمانِ، واجعلنا هُداةً مهتدين', 1, 'الدعاء بعد التشهُّد الأخير. (ص114–115)', '', '', 'اللهم بعلمك الغيب وقدرتك على الخلق أحيني ما علمت الحياة خيرا لي وتوفني إذا كانت الوفاة خيرا لي اللهم وأسألك خشيتك في الغيب والشهادة وأسألك كلمة الحق والعدل في الغضب والرضى وأسألك القصد في الفقر والغنى وأسألك نعيما لا يبيد وأسألك قرة عين لا تنفد ولا تنقطع وأسألك الرضا بعد القضاء وأسألك برد العيش بعد الموت وأسألك لذة النظر إلى وجهك وأسألك الشوق إلى لقائك في غير ضراء مضرة ولا فتنة مضلة اللهم زينا بزينة الإيمان واجعلنا هداة مهتدين', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (945, 15, 13, 'أحسنُ الكلامِ كلامُ اللهِ، وأحسنُ الهَدْيِ هَدْيُ محمدٍ صلى الله عليه وسلم', 1, 'الدعاء بعد التشهُّد الأخير. (ص115)', '', '', 'أحسن الكلام كلام الله وأحسن الهدي هدي محمد صلى الله عليه وسلم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1226, 15, 14, 'ولْيَكُنْ آخِرَ ما يقول بين التَّشَهُّدِ والتَّسْلِيمِ:', 0, 'الدعاء بعد التشهُّد الأخير. (ص115)', '', '', 'وليكن آخر ما يقول بين التشهد والتسليم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (133, 15, 15, 'اللهم اغفرْ لي ما قَدَّمْتُ، وما أَخَّرْتُ، وما أسررتُ، وما أعلنتُ، وما أسرفتُ، وما أنتَ أعلمُ به منِّي، أنتَ المُقَدِّمُ، وأنتَ المؤخِّرُ، لا إله إلا أنت', 1, 'الدعاء بعد التشهُّد الأخير. (ص115)', '', '', 'اللهم اغفر لي ما قدمت وما أخرت وما أسررت وما أعلنت وما أسرفت وما أنت أعلم به مني أنت المقدم وأنت المؤخر لا إله إلا أنت', '', '');
